function Field({ label, name, type = 'text', placeholder, defaultValue, required = false, className = '', autoComplete, minLength }: {
  label: string; name: string; type?: string; placeholder?: string; defaultValue?: string | number | null; required?: boolean; className?: string; autoComplete?: string; minLength?: number;
}) {
  return <label className={cx('grid gap-1.5 text-sm font-medium text-forest', className)}>
    <span>{label}{required && <span className="text-coral"> *</span>}</span>
    <input data-testid={`input-${name}`} name={name} type={type} autoComplete={autoComplete} minLength={minLength} required={required} placeholder={placeholder} defaultValue={defaultValue ?? ''} className="h-11 rounded-xl border border-sage-200 bg-cream/70 px-3.5 text-sm outline-none placeholder:text-forest/40 focus:border-lime-600 focus:ring-2 focus:ring-lime-200" />
  </label>;
}

function TextArea({ label, name, placeholder, defaultValue, required = false }: { label: string; name: string; placeholder?: string; defaultValue?: string | null; required?: boolean }) {
  return <label className="grid gap-1.5 text-sm font-medium text-forest">
    <span>{label}{required && <span className="text-coral"> *</span>}</span>
    <textarea data-testid={`textarea-${name}`} name={name} required={required} placeholder={placeholder} defaultValue={defaultValue ?? ''} rows={4} className="resize-none rounded-xl border border-sage-200 bg-cream/70 px-3.5 py-3 text-sm outline-none placeholder:text-forest/40 focus:border-lime-600 focus:ring-2 focus:ring-lime-200" />
  </label>;
}

