function StatusPill({ value }: { value?: string | null }) {
  const tone = value?.toUpperCase().includes('APPROV') || value?.toUpperCase() === 'OPEN' ? 'bg-lime-100 text-lime-800' :
    value?.toUpperCase().includes('REJECT') || value?.toUpperCase() === 'CLOSED' ? 'bg-coral/15 text-coral-700' : 'bg-sage-100 text-forest/70';
  return <span data-testid={`status-${value ?? 'unknown'}`} className={cx('inline-flex rounded-full px-2.5 py-1 font-mono text-[10px] font-bold uppercase tracking-wide', tone)}>{value?.replaceAll('_', ' ') || 'UNKNOWN'}</span>;
}

